-- Extend the curated, read-only projections without exposing draft content.
alter table public.ecosystem_regions add column if not exists explorer_data jsonb not null default '{}' check (jsonb_typeof(explorer_data) = 'object');
alter table public.ecosystem_hotspots add column if not exists explorer_data jsonb not null default '{}' check (jsonb_typeof(explorer_data) = 'object');

create or replace view public.ecosystem_public_regions with (security_invoker=true) as
select slug, title_de, title_en, biome, center_lat, center_lon, zoom_distance, icon_key,
       summary_de, ecological_role_de, source_citations, explorer_data
from public.ecosystem_regions
where status = 'published' and jsonb_array_length(source_citations) > 0;

create or replace view public.ecosystem_public_hotspots with (security_invoker=true) as
select h.slug, h.region_slug, h.title_de, h.latitude, h.longitude, h.icon_key, h.category,
       h.teaser_de, h.detail_de, h.priority, h.min_zoom, h.source_citations, h.related_paths, h.explorer_data
from public.ecosystem_hotspots h
join public.ecosystem_public_regions r on r.slug = h.region_slug
where h.status = 'published' and jsonb_array_length(h.source_citations) > 0;

insert into public.ecosystem_regions
  (slug,title_de,title_en,biome,center_lat,center_lon,summary_de,status,source_citations,explorer_data)
values ('guanica','Trockenwald von Guánica','Guánica dry forest','subtropical dry forest',17.96882,-66.86888,
  'Erkunde zwei untersuchte Standorte an Puerto Ricos trockener Südküste. Vom Baum auf felsigem Grund geht es bis zum gemessenen Bodenprofil.','published','[{"label":"NEON · Guánica Forest","url":"https://www.neonscience.org/field-sites/guan"}]'::jsonb,'{"media":{"path":"/nature/forest.webp","caption_de":"Guánica, Puerto Rico","caption_en":"Guánica, Puerto Rico","credit":"Oquendo","source":"https://commons.wikimedia.org/wiki/File:Gu%C3%A1nica_State_forest.jpg","license":"CC BY 2.0","license_url":"https://creativecommons.org/licenses/by/2.0/"},"summary_en":"Follow two field surveys on the dry southern coast of Puerto Rico, from a tree growing on exposed limestone to a measured soil profile."}'::jsonb);

insert into public.ecosystem_hotspots
  (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data)
values ('guanica-habitat','guanica',1,'habitat','Wald im Regenschatten','Die Cordillera Central beeinflusst, wo Regen fällt. An der Südküste treffen geringe Niederschläge auf hohe Verdunstung.','NEON unterscheidet im Reservat unter anderem laubabwerfenden Wald, halbimmergrünen Wald und küstennahes Gebüsch.',17.96882,-66.86888,'published','[{"label":"NEON · Guánica Forest","url":"https://www.neonscience.org/field-sites/guan"}]'::jsonb,'[]'::jsonb,'{"title_en":"Forest in a rain shadow","teaser_en":"The Cordillera Central affects where rain falls. The south coast has low rainfall and high evapotranspiration.","detail_en":"NEON distinguishes deciduous forest, semi-evergreen forest and coastal scrub within the reserve.","media":{"path":"/nature/forest.webp","caption_de":"Guánica, Puerto Rico","caption_en":"Guánica, Puerto Rico","credit":"Oquendo","source":"https://commons.wikimedia.org/wiki/File:Gu%C3%A1nica_State_forest.jpg","license":"CC BY 2.0","license_url":"https://creativecommons.org/licenses/by/2.0/"}}'::jsonb);

insert into public.ecosystem_hotspots
  (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data)
values ('guanica-yaiti','guanica',2,'plant','Yaití auf Kalkfels','Auf der Probefläche GUAN_012 fanden Forschende Gymnanthes lucida in einem Trockenwald mit viel offenem Kalkfels.','Auch Thouinia striata var. portoricensis wurde dort erfasst. Das Artfoto zeigt ein Exemplar derselben Art auf Key Largo in Florida.',17.95146,-66.89913,'published','[{"label":"NEON · GUAN_012 (2018)","url":"https://data.neonscience.org/documents/10179/2361410/GUAN_PedonDescription_2018-11-15/0224d08c-8444-d29f-d2d4-6b131485f670?version=1.0"}]'::jsonb,'[]'::jsonb,'{"title_en":"Yaití on limestone","teaser_en":"Researchers recorded Gymnanthes lucida on plot GUAN_012 in dry forest with extensive exposed limestone.","detail_en":"Thouinia striata var. portoricensis was recorded there too. The species photograph shows a specimen on Key Largo, Florida.","media":{"path":"/nature/oysterwood.webp","caption_de":"Gymnanthes lucida · Artfoto aus Florida","caption_en":"Gymnanthes lucida · species photo from Florida","credit":"Jason Hollinger","source":"https://commons.wikimedia.org/wiki/File:Crabwood_or_Oysterwood_-_Flickr_-_pellaea_(4).jpg","license":"CC BY 2.0","license_url":"https://creativecommons.org/licenses/by/2.0/"},"taxon":"Gymnanthes lucida","plot_id":"GUAN_012","observed_on":"2018-06-21"}'::jsonb);

insert into public.ecosystem_hotspots
  (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data)
values ('guanica-oberboden','guanica',3,'soil','Wurzeln im Oberboden','Am zweiten Standort ist der Oberboden dunkelgrau und krümelig. Feine und mittelstarke Wurzeln durchziehen die oberen 30 cm.','NEON beschreibt tonigen Lehm. Die Korngrößen beschreiben die Textur. Die Krümel zeigen, wie sich die Teilchen im ungestörten Boden zusammenlagern.',17.96882,-66.86888,'published','[{"label":"NEON · S2015PR055001","url":"https://www.neonscience.org/data-collection/soils/soil-descriptions/guan"}]'::jsonb,'["/products/leafer-substrat-konfigurator"]'::jsonb,'{"title_en":"Roots in the topsoil","teaser_en":"At the second site the topsoil is dark gray and granular. Fine and medium roots run through its upper 30 cm.","detail_en":"NEON describes a clay loam. Particle sizes describe texture. Granules show how particles aggregate in undisturbed soil.","media":{"path":"/nature/profile.webp","caption_de":"Originalprofil · Guánica, 0–93 cm","caption_en":"Field profile · Guánica, 0–93 cm","credit":"NEON","source":"https://www.neonscience.org/data-collection/soils/soil-descriptions/guan","license":"CC BY 4.0","license_url":"https://creativecommons.org/licenses/by/4.0/"},"plot_id":"S2015PR055001","observed_on":"2015-04-09","horizon":"A","depth_cm":[0,30],"ph":7.5}'::jsonb);

insert into public.ecosystem_hotspots
  (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data)
values ('guanica-unterboden','guanica',4,'soil','Woher kommt der Kalk?','Hier verwittern Kalkstein und Schluffstein. Zwischen 30 und 55 cm dokumentierte NEON sichtbare Karbonatanreicherungen und einen pH-Wert von 8,0.','Für die Topfkultur ist das eine Vergleichsfrage. Welche Struktur und Wasserversorgung braucht deine eigene Pflanze im gewählten Gefäß?',17.96882,-66.86888,'published','[{"label":"NEON · S2015PR055001","url":"https://www.neonscience.org/data-collection/soils/soil-descriptions/guan"}]'::jsonb,'["/products/leafer-substrat-konfigurator"]'::jsonb,'{"title_en":"Where does the carbonate come from?","teaser_en":"Limestone and siltstone weather at this site. Between 30 and 55 cm NEON documented carbonate accumulations and a pH of 8.0.","detail_en":"For container growing, consider which structure and water supply your own plant needs in its pot.","media":{"path":"/nature/profile.webp","caption_de":"Originalprofil · Guánica, 0–93 cm","caption_en":"Field profile · Guánica, 0–93 cm","credit":"NEON","source":"https://www.neonscience.org/data-collection/soils/soil-descriptions/guan","license":"CC BY 4.0","license_url":"https://creativecommons.org/licenses/by/4.0/"},"plot_id":"S2015PR055001","observed_on":"2015-04-09","horizon":"Bk1","depth_cm":[30,55],"ph":8.0}'::jsonb);
